// @ts-check
// A helper worker of one index build (idx-aiuti.js): decodes the arrays of the spectra it is given (mzlab-wasm decode_job) and answers in the job's
// shared slot: state 1 with the answer, 2 when it does not decode or does not fit (the builder then decodes that spectrum itself).
// @ts-ignore the engine is generated by wasm-bindgen: it is not in the tree
import init, { decode_job } from "./wasm/mzlab_wasm.js";

const HEAD = 16;
/** @type {Promise<boolean> | null} */ let ready = null;

onmessage = async ev => {
  const m = ev.data;
  // the builder starts only once its helpers say they are ready: it never yields, so a helper still loading would never answer
  if (m.op === "module") { const r = ready = (m.module ? init({ module_or_path: m.module }) : init()).then(() => true, () => false); r.then(ok => postMessage({ op: "ready", ok })); return; }
  if (m.op !== "job") return;
  const ok = ready ? await ready : false;
  const i32 = new Int32Array(m.sab, 0, 4);
  let state = 2;
  if (ok) {
    try {
      /** @type {Uint8Array | undefined} */ const out = decode_job(new Uint8Array(m.sab, HEAD, Atomics.load(i32, 1)));
      if (out && HEAD + out.length <= m.sab.byteLength) { new Uint8Array(m.sab, HEAD, out.length).set(out); Atomics.store(i32, 2, out.length); state = 1; }
    } catch (_) { /* lost instance: the builder decodes it */ }
  }
  Atomics.store(i32, 0, state);
  Atomics.notify(i32, 0);
};
